const VAPID_PUBLIC_KEY =
  "BGbv4i2BfU6a-nfOd49_-ykPhchNeGSvSHLNSxt6PhyY2jZNlpsWkUETRyNsm7bSmrOMk5o883cDsqy1aifX6Cw";
const VAPID_HUB_V1_EXT_ID = "three_youths_vapid_hub_v1";
const VAPID_HUB_V2_EXT_ID = "three_youths_vapid_hub_v2";
const ANNOUNCEMENTS_HUB_OS_ID = "2066d63c-d32e-44ec-8ee4-2ce445c79c38";

const OFFICIAL_NOTIFICATION_TITLE = "الثلاثة فتية - اجتماع الشباب السوداني";
const SW_STATE_CACHE = "three_youths_sw_state_v20";
const SW_STATE_URL = "/__sw_user_state_v9__.json";
const SUPABASE_URL = "https://jkuvkkitkmemqopbrhin.supabase.co";
