// In-Memory Base64 PNG Assets (Zero Network Latency, 100% Full Original Colors + Transparent Status Bar Badge)
const COLOR_EMBLEM_RAW_B64 = "";
const EMBLEM_RAW_B64 = "";
const EMPTY_RAW_B64 = "iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAAGklEQVR4Ae3BAQEAAACCoP6vdkjAAAAAgHsBECAAAbGjFMwAAAAASUVORK5CYII=";

function base64ToUint8Array(b64) {
  try {
    const clean = String(b64 || "").replace(/^data:[^,]+,/, "").replace(/\s+/g, "");
    const raw = atob(clean);
    const arr = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) {
      arr[i] = raw.charCodeAt(i);
    }
    return arr;
  } catch {
    return new Uint8Array(0);
  }
}

const COLOR_EMBLEM_PNG_BYTES = base64ToUint8Array(COLOR_EMBLEM_RAW_B64);
const EMBLEM_PNG_BYTES = base64ToUint8Array(EMBLEM_RAW_B64);
const EMPTY_PNG_BYTES = base64ToUint8Array(EMPTY_RAW_B64);

let swUserContext = null;
const swNotifiedIds = new Set();
let swPollTimer = null;
let swStateLoaded = false;

function urlBase64ToUint8Array(base64String) {
  const padding = "=".repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
  const rawData = atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i);
  }
  return outputArray;
}

function arrayBufferToBase64(buffer) {
  if (!buffer) return "";
  const bytes = new Uint8Array(buffer);
  let binary = "";
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function fnv1aHashHex(str) {
  let hash = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return {
    hex: hash.toString(16).padStart(8, "0"),
    bucket: hash % 2
  };
}

function doesSwSubscriptionMatchVapidKey(sub, expectedKeyBytes) {
  try {
    const subKeyBuf = sub && sub.options && sub.options.applicationServerKey;
    if (!subKeyBuf) return false;
    const actualBytes = new Uint8Array(subKeyBuf);
    if (actualBytes.length !== expectedKeyBytes.length) return false;
    for (let i = 0; i < actualBytes.length; i++) {
      if (actualBytes[i] !== expectedKeyBytes[i]) return false;
    }
    return true;
  } catch {
    return false;
  }
}

async function preCacheNotificationIcons() {
  try {
    const cache = await caches.open(SW_STATE_CACHE);
    const headers = {
      "Content-Type": "image/png",
      "Cache-Control": "public, max-age=31536000, immutable"
    };
    await Promise.all([
      cache.put("/icon-192x192.png", new Response(COLOR_EMBLEM_PNG_BYTES, { headers })),
      cache.put("/icon-192x192.png?v=3", new Response(COLOR_EMBLEM_PNG_BYTES, { headers })),
      cache.put("/apple-touch-icon.png", new Response(COLOR_EMBLEM_PNG_BYTES, { headers })),
      cache.put("/apple-touch-icon.png?v=3", new Response(COLOR_EMBLEM_PNG_BYTES, { headers }))
    ]);
  } catch {}
}

// Intercept notification icon & badge requests and serve them synchronously from RAM in 0ms
self.addEventListener("fetch", (event) => {
  try {
    const url = event.request && event.request.url ? String(event.request.url) : "";
    if (
      url.includes("/icon-192x192.png") ||
      url.includes("/notif-logo-color.png") ||
      url.includes("/notif-logo-emblem.png") ||
      url.includes("/site-badge.png")
    ) {
      event.respondWith(
        new Response(COLOR_EMBLEM_PNG_BYTES, {
          status: 200,
          headers: {
            "Content-Type": "image/png",
            "Cache-Control": "public, max-age=31536000, immutable"
          }
        })
      );
      return;
    }
  } catch {}
});

async function ensureSwPushSubscriptionSynced() {
  try {
    if (!self.registration || !self.registration.pushManager) return;
    if (typeof Notification !== "undefined" && Notification.permission !== "granted") {
      return;
    }

    const expectedKeyBytes = urlBase64ToUint8Array(VAPID_PUBLIC_KEY);
    let sub = await self.registration.pushManager.getSubscription();

    if (sub && !doesSwSubscriptionMatchVapidKey(sub, expectedKeyBytes)) {
      try {
        await sub.unsubscribe();
      } catch {}
      sub = null;
    }

    if (!sub) {
      sub = await self.registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: expectedKeyBytes
      });
    }

    if (!sub || !sub.endpoint) return;

    const p256dh = arrayBufferToBase64(sub.getKey ? sub.getKey("p256dh") : null);
    const auth = arrayBufferToBase64(sub.getKey ? sub.getKey("auth") : null);
    if (!p256dh || !auth) return;

    const fullNameClean = String((swUserContext && swUserContext.fullName) || "").trim();
    const firstName = fullNameClean.split(/\s+/)[0] || "أخي الحبيب";
    const { hex, bucket } = fnv1aHashHex(sub.endpoint);
    const subKey = `s_${hex}`;
    const targetHubExtId = bucket === 0 ? VAPID_HUB_V1_EXT_ID : VAPID_HUB_V2_EXT_ID;

    const compactRecord = {
      ep: sub.endpoint,
      p256: p256dh,
      auth,
      id: (swUserContext && swUserContext.id) || "",
      name: firstName.slice(0, 24),
      full: fullNameClean.slice(0, 48),
      role: (swUserContext && swUserContext.role) || "member",
      g: (swUserContext && swUserContext.gender) || "male"
    };

    await fetch(`https://api.onesignal.com/apps/${ONESIGNAL_APP_ID}/users`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json"
      },
      body: JSON.stringify({
        identity: { external_id: targetHubExtId },
        properties: {
          tags: {
            [subKey]: JSON.stringify(compactRecord)
          }
        }
      })
    });
  } catch {}
}

async function saveSwState() {
  try {
    const cache = await caches.open(SW_STATE_CACHE);
    const data = JSON.stringify({
      user: swUserContext,
      notifiedIds: Array.from(swNotifiedIds).slice(-300)
    });
    await cache.put(
      SW_STATE_URL,
      new Response(data, { headers: { "Content-Type": "application/json" } })
    );
  } catch {}
}

async function loadSwState() {
  if (swStateLoaded) return;
  swStateLoaded = true;
  try {
    const cache = await caches.open(SW_STATE_CACHE);
    const res = await cache.match(SW_STATE_URL);
    if (res) {
      const parsed = await res.json();
      if (parsed && parsed.user && !swUserContext) {
        swUserContext = parsed.user;
      }
      if (parsed && Array.isArray(parsed.notifiedIds)) {
        parsed.notifiedIds.forEach((id) => swNotifiedIds.add(id));
      }
    }
  } catch {}
}

function formatPersonalizedMessage(rawText) {
  const firstName =
    (swUserContext?.fullName || "أخي الحبيب").trim().split(/\s+/)[0] || "أخي الحبيب";
  return String(rawText || "")
    .replace(/\[الاسم الأول\]/g, firstName)
    .replace(/\[الاسم الاول\]/g, firstName)
    .replace(/\[الاسم\]/g, firstName)
    .replace(/\bفلان\b/g, firstName)
    .replace(/\{name\}/gi, firstName)
    .replace(/\{first_name\}/gi, firstName);
}

function isAnnouncementTargetedForSwUser(ann, user) {
  if (!ann || !ann.id) return false;
  if (!user) return true;

  const role = user.role || "member";
  const memberId = user.id || "";
  const fullName = (user.fullName || "").trim();
  const gender = user.gender || "male";
  const isOwner = role === "community_owner";

  if (
    ann.isVisitationTaskAlert ||
    ann.targetAudience === "servant_personal" ||
    (ann.title &&
      ann.title.includes("تكليف افتقاد") &&
      (ann.targetUserId || ann.targetServantName))
  ) {
    if (isOwner) return false;
    if (!memberId && !fullName) return false;
    const targetName = (ann.targetServantName || "").trim();
    return Boolean(
      (ann.targetUserId && memberId && ann.targetUserId === memberId) ||
        (targetName &&
          fullName &&
          (fullName === targetName ||
            fullName.includes(targetName) ||
            targetName.includes(fullName)))
    );
  }

  if (
    ann.targetAudience === "community_owner_only" ||
    (ann.title && ann.title.startsWith("🔄 تحديث بيانات:"))
  ) {
    return isOwner;
  }

  if (!ann.targetAudience || ann.targetAudience === "all") return true;
  if (ann.targetAudience === "males_only") return gender === "male" || isOwner;
  if (ann.targetAudience === "females_only") return gender === "female" || isOwner;

  return true;
}

async function notifyOpenClientsToSyncAnnouncements(ann, extraMsg = {}) {
  try {
    const clients = await self.clients.matchAll({
      type: "window",
      includeUncontrolled: true
    });
    for (const client of clients) {
      try {
        client.postMessage({
          type: "SW_ANNOUNCEMENT_RECEIVED",
          announcement: ann || null,
          ...extraMsg
        });
      } catch {}
    }
  } catch {}
}

async function fetchLatestAnnouncementsForSw() {
  const results = [];
  const seenIds = new Set();
  const deletedSet = new Set();

  try {
    const hubRes = await fetch(
      `https://api.onesignal.com/apps/${ONESIGNAL_APP_ID}/users/by/onesignal_id/${ANNOUNCEMENTS_HUB_OS_ID}`,
      {
        headers: { Accept: "application/json" },
        cache: "no-store"
      }
    );
    if (hubRes.ok) {
      const hubData = await hubRes.json();
      const tags = (hubData && hubData.properties && hubData.properties.tags) || {};
      if (tags.del_ids) {
        try {
          const parsedDel = JSON.parse(tags.del_ids);
          if (Array.isArray(parsedDel)) {
            parsedDel.forEach((dId) => deletedSet.add(String(dId)));
          }
        } catch {}
      }
      if (tags.idx) {
        try {
          const idxObj = JSON.parse(tags.idx);
          if (Array.isArray(idxObj.d)) {
            idxObj.d.forEach((dId) => deletedSet.add(String(dId)));
          }
        } catch {}
      }
      for (const [k, rawVal] of Object.entries(tags)) {
        if (
          (k !== "latest_ann" && !k.startsWith("slot_") && !k.startsWith("a_")) ||
          !rawVal ||
          typeof rawVal !== "string"
        ) {
          continue;
        }
        try {
          const parsedAnn = JSON.parse(rawVal);
          if (
            parsedAnn &&
            parsedAnn.id &&
            !deletedSet.has(parsedAnn.id) &&
            !seenIds.has(parsedAnn.id)
          ) {
            seenIds.add(parsedAnn.id);
            results.push(parsedAnn);
          }
        } catch {}
      }
    }
  } catch {}

  return results;
}

async function showPhoneShadeNotification(bodyText, optionsExtra = {}) {
  const tag = optionsExtra.tag || `ty_notif_${Date.now()}`;
  const dataPayload = optionsExtra.data || {
    url: optionsExtra.url || "/",
    announcementId: optionsExtra.announcementId || null
  };

  const origin = self.location && self.location.origin ? self.location.origin : "";
  const colorLogoUrl = optionsExtra.icon || `${origin}/icon-192x192.png?v=3`;
  const monoBadgeUrl = optionsExtra.badge || `${origin}/icon-192x192.png?v=3`;

  const primaryOpts = {
    body: bodyText,
    icon: colorLogoUrl,
    badge: monoBadgeUrl,
    tag,
    renotify: true,
    requireInteraction: false,
    silent: false,
    dir: "rtl",
    lang: "ar",
    vibrate: [200, 100, 200],
    data: dataPayload
  };

  if (optionsExtra.image && String(optionsExtra.image).startsWith("http")) {
    primaryOpts.image = optionsExtra.image;
  }

  try {
    await self.registration.showNotification(OFFICIAL_NOTIFICATION_TITLE, primaryOpts);
    return true;
  } catch {
    try {
      await self.registration.showNotification(OFFICIAL_NOTIFICATION_TITLE, {
        body: bodyText,
        icon: colorLogoUrl,
        badge: monoBadgeUrl,
        tag,
        dir: "rtl",
        lang: "ar",
        data: dataPayload
      });
      return true;
    } catch {
      return false;
    }
  }
}

async function displayAnnouncementInPhoneShade(ann) {
  if (!ann || !ann.id || swNotifiedIds.has(ann.id)) return;
  swNotifiedIds.add(ann.id);
  await saveSwState();

  await notifyOpenClientsToSyncAnnouncements(ann);

  const formattedBody = formatPersonalizedMessage(ann.content || "");
  await showPhoneShadeNotification(formattedBody, {
    tag: `ann_${ann.id}`,
    url: `/?annId=${encodeURIComponent(ann.id)}`,
    announcementId: ann.id,
    image:
      ann.imageUrl && String(ann.imageUrl).startsWith("http") ? ann.imageUrl : undefined
  });
}

async function checkServerAnnouncementsInBackground() {
  try {
    await loadSwState();
    const announcements = await fetchLatestAnnouncementsForSw();
    if (!Array.isArray(announcements) || announcements.length === 0) return;

    const nowMs = Date.now();
    for (const ann of announcements) {
      if (!ann || !ann.id || swNotifiedIds.has(ann.id)) continue;

      const createdMs = ann.createdAt ? new Date(ann.createdAt).getTime() : 0;
      if (createdMs > 0 && nowMs - createdMs > 60 * 60 * 1000) {
        swNotifiedIds.add(ann.id);
        await saveSwState();
        continue;
      }

      if (swUserContext && !isAnnouncementTargetedForSwUser(ann, swUserContext)) {
        swNotifiedIds.add(ann.id);
        await saveSwState();
        continue;
      }

      await displayAnnouncementInPhoneShade(ann);
    }
  } catch {}
}

function startBackgroundWatcher() {
  if (swPollTimer) return;
  swPollTimer = setInterval(checkServerAnnouncementsInBackground, 10000);
}

self.addEventListener("install", (event) => {
  self.skipWaiting();
  event.waitUntil(Promise.all([loadSwState(), preCacheNotificationIcons()]));
  startBackgroundWatcher();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    Promise.all([
      self.clients.claim(),
      preCacheNotificationIcons(),
      loadSwState().then(() => ensureSwPushSubscriptionSynced())
    ])
  );
  startBackgroundWatcher();
});

self.addEventListener("pushsubscriptionchange", (event) => {
  event.waitUntil(loadSwState().then(() => ensureSwPushSubscriptionSynced()));
});

self.addEventListener("periodicsync", (event) => {
  if (event.tag === "three-youths-announcements-sync") {
    event.waitUntil(checkServerAnnouncementsInBackground());
  }
});

self.addEventListener("sync", (event) => {
  event.waitUntil(checkServerAnnouncementsInBackground());
});

// Native W3C Web Push Event Listener (Wakes up phone via FCM/APNs even when app & browser are 100% closed)
self.addEventListener("push", (event) => {
  event.waitUntil(
    (async () => {
      await Promise.all([loadSwState(), preCacheNotificationIcons()]);
      let payload = null;
      if (event.data) {
        try {
          payload = event.data.json();
        } catch {
          try {
            const txt = event.data.text();
            if (txt) payload = { body: txt };
          } catch {}
        }
      }

      if (!payload) {
        await checkServerAnnouncementsInBackground();
        return;
      }

      const customData =
        (payload && payload.custom && payload.custom.a) ||
        (payload && payload.data) ||
        {};
      const annId =
        customData.announcementId ||
        payload.announcementId ||
        (payload && payload.custom && payload.custom.i) ||
        `push_${Date.now()}`;

      const rawBody =
        payload.rawContent ||
        payload.alert ||
        payload.body ||
        payload.message ||
        (payload.contents && (payload.contents.ar || payload.contents.en)) ||
        "إشعار جديد من اجتماع الشباب السوداني - الثلاثة فتية";

      // Construct full announcement object immediately from push payload so MemberAnnouncements updates in 0ms!
      const incomingAnn = payload.announcement || {
        id: annId,
        title: customData.annTitle || OFFICIAL_NOTIFICATION_TITLE,
        content: payload.rawContent || rawBody,
        templateType: customData.templateType || "custom",
        senderRole: customData.senderRole || "community_owner",
        senderName: customData.senderName || OFFICIAL_NOTIFICATION_TITLE,
        targetAudience: customData.targetAudience || "all",
        targetUserId: customData.targetUserId || undefined,
        targetServantName: customData.targetServantName || undefined,
        isVisitationTaskAlert: Boolean(customData.isVisitationTaskAlert),
        imgOsIds: customData.imgOsIds || undefined,
        annOsId: customData.annOsId || undefined,
        vrOsId: customData.vrOsId || undefined,
        imageUrl: payload.image || undefined,
        createdAt: customData.createdAt || new Date().toISOString(),
        pinned: true
      };

      await notifyOpenClientsToSyncAnnouncements(incomingAnn, {
        imgOsIds: customData.imgOsIds || (incomingAnn && incomingAnn.imgOsIds) || null,
        annOsId: customData.annOsId || (incomingAnn && incomingAnn.annOsId) || null,
        vrOsId: customData.vrOsId || (incomingAnn && incomingAnn.vrOsId) || null
      });

      if (annId && swNotifiedIds.has(annId)) {
        return;
      }

      if (swUserContext && customData.targetAudience) {
        const syntheticAnn = {
          id: annId,
          title: payload.title || "",
          targetAudience: customData.targetAudience,
          targetUserId: customData.targetUserId,
          targetServantName: customData.targetServantName
        };
        if (!isAnnouncementTargetedForSwUser(syntheticAnn, swUserContext)) {
          swNotifiedIds.add(annId);
          await saveSwState();
          return;
        }
      }

      if (annId) {
        swNotifiedIds.add(annId);
        await saveSwState();
      }

      const formattedBody = formatPersonalizedMessage(
        payload.body || payload.alert || payload.message || rawBody
      );
      const targetUrl =
        (payload && payload.custom && payload.custom.u) ||
        payload.url ||
        (customData.announcementId
          ? `/?annId=${encodeURIComponent(customData.announcementId)}`
          : "/");

      await showPhoneShadeNotification(formattedBody, {
        tag: `ann_${annId}`,
        url: targetUrl,
        announcementId: customData.announcementId || annId,
        image: payload.image || payload.big_picture || payload.chrome_web_image
      });
    })()
  );
});

self.addEventListener("message", (event) => {
  const payload = event.data;
  if (!payload) return;

  if (payload.type === "SKIP_WAITING") {
    self.skipWaiting();
    return;
  }

  if (payload.type === "SYNC_SW_USER_CONTEXT") {
    swUserContext = payload.user || null;
    if (Array.isArray(payload.seenIds)) {
      payload.seenIds.forEach((id) => swNotifiedIds.add(id));
    }
    event.waitUntil(
      Promise.all([
        preCacheNotificationIcons(),
        saveSwState().then(() => ensureSwPushSubscriptionSynced())
      ])
    );
    startBackgroundWatcher();
    return;
  }

  if (payload.type === "MARK_ANNOUNCEMENT_NOTIFIED" && payload.announcementId) {
    swNotifiedIds.add(payload.announcementId);
    event.waitUntil(saveSwState());
    return;
  }

  if (payload.type === "CHECK_ANNOUNCEMENTS_NOW") {
    event.waitUntil(checkServerAnnouncementsInBackground());
    return;
  }

  if (payload.type !== "SHOW_NATIVE_NOTIFICATION") return;

  const forceShow = Boolean(payload.force);
  const incomingOpts = payload.options || {};
  const annId = payload.announcementId || incomingOpts.tag || `ann_${Date.now()}`;
  if (!forceShow && swNotifiedIds.has(annId)) {
    if (event.ports && event.ports[0]) {
      event.ports[0].postMessage({ ok: false, reason: "already_notified" });
    }
    return;
  }
  swNotifiedIds.add(annId);

  const rawBody = payload.body || incomingOpts.body || "";
  const formattedBody = formatPersonalizedMessage(rawBody);
  const tag = forceShow
    ? `test_${Date.now()}`
    : payload.tag || incomingOpts.tag || `ann_${annId}`;
  const url = payload.url || (incomingOpts.data && incomingOpts.data.url) || "/";
  const rawImg = payload.image || incomingOpts.image;

  event.waitUntil(
    (async () => {
      await Promise.all([saveSwState(), preCacheNotificationIcons()]);
      const ok = await showPhoneShadeNotification(formattedBody, {
        tag,
        url,
        announcementId:
          payload.announcementId ||
          (incomingOpts.data && incomingOpts.data.announcementId) ||
          null,
        image: rawImg
      });
      if (event.ports && event.ports[0]) {
        try {
          event.ports[0].postMessage({ ok });
        } catch {}
      }
    })()
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();

  const notifData = event.notification.data || {};
  const targetUrl = notifData.url || "/";
  const announcementId = notifData.announcementId || null;

  event.waitUntil(
    self.clients
      .matchAll({ type: "window", includeUncontrolled: true })
      .then((clientList) => {
        for (const client of clientList) {
          if ("focus" in client) {
            client.focus();
            client.postMessage({
              type: "NOTIFICATION_CLICKED",
              announcementId,
              url: targetUrl
            });
            return;
          }
        }
        if (self.clients.openWindow) {
          const openUrl = announcementId
            ? `${targetUrl}${targetUrl.includes("?") ? "&" : "?"}annId=${encodeURIComponent(
                announcementId
              )}`
            : targetUrl;
          return self.clients.openWindow(openUrl);
        }
      })
  );
});
